const resources: Record<UiLanguage, Record<TranslationKey, string>> = { tr, en };

function interpolate(template: string, values?: TranslationValues) {
  if (!values) return template;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (match, key: string) => values[key] === undefined ? match : String(values[key]));
}

export function translate(language: UiLanguage, key: TranslationKey, values?: TranslationValues) {
  return interpolate(resources[language][key] ?? resources.en[key], values);
}

type I18nValue = {
  language: UiLanguage;
  locale: string;
  t: (key: TranslationKey, values?: TranslationValues) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: string | number | Date, options?: Intl.DateTimeFormatOptions) => string;
};

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ language, children }: { language: UiLanguage; children: ReactNode }) {
  const value = useMemo<I18nValue>(() => {
    const locale = language === 'tr' ? 'tr-TR' : 'en-US';
    return {
      language,
      locale,
      t: (key, values) => translate(language, key, values),
      formatNumber: (number, options) => new Intl.NumberFormat(locale, options).format(number),
      formatDate: (date, options) => new Intl.DateTimeFormat(locale, options).format(new Date(date)),
    };
  }, [language]);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  return <I18nContext.Provider value={value}><div className="i18n-root">{children}</div></I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error('useI18n must be used inside I18nProvider.');
  return context;
}
